    for top in range(0, h, 4):
        if top + 2 >= h:
            break
        for left in (0, 4):
            patch = [grid[top+i][left:left+3] for i in range(3)]
            color = next((v for row in patch for v in row if v not in (0, 4)), 0)
            if color:
                figures.append((color, sum(v == color for row in patch for v in row)))

    # Start below the marker. The pattern density determines whether the
    # glyph is horizontal or vertical.
    row = 1
    for color, count in figures:
        if row >= h:
            break
        if count >= 6:
