    out = [[0] * 7 for _ in range(h)]

    # Compact each 3x3 motif by its characteristic direction:
    # the asymmetric motifs become horizontal or vertical strokes.
    def draw(top, left, color, cells):
        for dr, dc in cells:
            r, c = top + dr, left + dc
            if 0 <= r < h and 0 <= c < 7:
                out[r][c] = color

    marker = next(((r, c) for r, row in enumerate(grid)
                   for c, v in enumerate(row) if v == 5), None)
    if marker:
        r, c = marker
        out[r][max(0, min(6, c - 8))] = 5

    # Tiles occur in 4-row bands; retain their order and render a compact
    # representative at the corresponding band.
    for top in range(0, h - 2, 4):
        for left in (0, 4):
            patch = [grid[top+i][left:left+3] for i in range(3)]
            color = next((v for row in patch for v in row if v not in (0, 4)), 0)
            if not color:
                continue
            n = sum(v == color for row in patch for v in row)
            if n >= 7:
                draw(top, 1, color, [(1,0), (1,1), (1,2), (1,3)])
            elif n >= 5:
                draw(top, 2, color, [(1,0), (1,1)])
            else:
                draw(top, 4, color, [(0,0), (1,0)])
    return out
